    quy['dt'] = _h_dates(quy['Thời gian'])
    quy['Giá trị_n'] = _h_mnum(quy['Giá trị'])
    return dict(hd=hd, ct=ct, sp=sp, dv=dv, kh=kh, nhap=nhap, ctn=ctn, ton=ton, quy=quy)

