        mult = 1000.0
        s = s[:-1]
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    else:
        s = s.replace(',', '') if s.count(',') else s
    s = re.sub('[^0-9.\\-]', '', s)
