import re, unicodedata
import pandas as pd, numpy as np

def _h_norm(s):
    s = str(s).lower().replace('đ', 'd')
    s = unicodedata.normalize('NFD', s).encode('ascii', 'ignore').decode()
    return re.sub('\\s+', ' ', s).strip()

def _h_money(s):
    if isinstance(s, (int, float, np.integer, np.floating)) and (not isinstance(s, bool)):
        return float(s)
    s = str(s).strip().lower().replace('đ', '').replace('₫', '')
    if not s or s in ('nan', 'none'):
        return np.nan
    s = s.replace(' ', '')
    mult = 1.0
    if 'tr' in s:
        mult = 1000000.0
        s = s.replace('tr', '')
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    elif s.endswith('k'):
        mult = 1000.0
        s = s[:-1]
    s = s.replace(',', '')
    s = re.sub('[^0-9.\\-]', '', s)
    if s in ('', '-', '.'):
        return np.nan
    try:
        return float(s) * mult
    except Exception:
        return np.nan

def _h_mnum(col):
    return pd.Series(col).map(_h_money)

def _h_dates(col):
    s = pd.Series(col)
    if pd.api.types.is_datetime64_any_dtype(s):
        return s
    out = pd.Series(pd.NaT, index=s.index, dtype='datetime64[ns]')
    num = pd.to_numeric(s, errors='coerce')
    mask = num.notna() & (num > 1000) & (num < 100000)
    if mask.any():
        out.loc[mask] = pd.Timestamp('1899-12-30') + pd.to_timedelta(num.loc[mask], unit='D')
    rest = s.notna() & ~mask
    if rest.any():
        t = s.loc[rest].astype(str).str.strip()
        parts = t.str.extract('^(\\d{1,4})[-/](\\d{1,2})[-/](\\d{1,4})')
        parsed = pd.Series(pd.NaT, index=t.index, dtype='datetime64[ns]')
        okp = parts.notna().all(axis=1)
        if okp.any():
            (a, bb, c) = (parts.loc[okp, 0], parts.loc[okp, 1], parts.loc[okp, 2])
            year = c.where(c.str.len() == 4, a)
            month = bb
            day = a.where(c.str.len() == 4, c)
            parsed.loc[okp] = pd.to_datetime(pd.DataFrame({'year': year.astype(int), 'month': month.astype(int), 'day': day.astype(int)}), errors='coerce')
        out.loc[rest] = parsed
    return out
_h__b = None

def _h_tables():
    global _h__b
    if _h__b is None:
        b = data
        nfc = {unicodedata.normalize('NFC', k): k for k in b}
        ct = b[nfc['So_chi_tiet_ban_hang__all']].copy()
        sp = b[nfc['Danh sách hàng hóa']].copy()
        ct['dt'] = _h_dates(ct['Ngày'])
        st = ct['Trạng thái'].astype(str).str.strip()
        ct['st_norm'] = np.select([st.str.contains('huỷ|hủy|cancel|hủy', case=False, na=False), st.str.contains('trả|return', case=False, na=False)], ['cancel', 'return'], default='ok')
        ct['ttien'] = _h_mnum(ct['Thành tiền'])
        ct['gia'] = _h_mnum(ct['Đơn giá'])
        ct['slqd'] = pd.to_numeric(ct['Số lượng quy đổi'], errors='coerce')
        ct['name_n'] = ct['Tên hàng hóa'].map(_h_norm)
        sp['name_n'] = sp['Tên hàng hóa'].map(_h_norm)
        sp['group_n'] = sp['Nhóm hàng hóa'].map(_h_norm)
        cmap = sp.drop_duplicates('name_n').set_index('name_n')
        ct['group_n'] = ct['name_n'].map(cmap['group_n'])
        _h__b = dict(ct=ct, sp=sp)
    return _h__b

def _h_month_mask(dt, y, m):
    s = pd.Timestamp(year=y, month=m, day=1)
    e = s + pd.offsets.MonthBegin(1)
    return (dt >= s) & (dt < e)

def _h_product_qty(ct, start, end, name):
    (s, e) = (pd.Timestamp(start), pd.Timestamp(end) + pd.Timedelta(days=1))
    sub = ct[(ct['st_norm'] == 'ok') & (ct['dt'] >= s) & (ct['dt'] < e)]
    return float(sub.loc[sub['name_n'] == _h_norm(name), 'slqd'].sum())

