def _h_money(s):
    """Parse Vietnamese money strings ('240,000', '45k', '1,45tr')."""
    if isinstance(s, (int, float, np.integer, np.floating)) and (not isinstance(s, bool)):
        return float(s)
    s = str(s).strip().lower().replace('đ', '').replace('₫', '')
    if not s or s in ('nan', 'none'):
        return np.nan
    s = s.replace(' ', '')
    mult = 1.0
    if 'tr' in s:
        mult = 1000000.0
        s = s.replace('tr', '')
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    elif s.endswith('k'):
        mult = 1000.0
        s = s[:-1]
        if ',' in s and '.' not in s:
            s = s.replace(',', '.')
        s = s.replace(',', '')
    else:
        s = s.replace(',', '') if s.count(',') else s
    s = re.sub('[^0-9.\\-]', '', s)
    if s in ('', '-', '.'):
        return np.nan
    try:
        return float(s) * mult
